"""Build a local report using only checksummed hosted aggregate outputs."""
from pathlib import Path
import hashlib
import html
import json
import sys
from datetime import datetime, timezone
sys.path.insert(0, str(Path(__file__).resolve().parents[1]))
from research.studies.checkpoint_20261031.capm_review import decode_fragments, audit_metrics
ROOT = Path('.local/capm-spy-v1')
OUT = Path('.local/performance/capm-spy-v1')


def main():
    OUT.mkdir(parents=True, exist_ok=True)
    plan = json.loads(Path('research/plans/capm-spy-v1.json').read_text())
    results, audits = {}, []
    for case in ['probe', 'capm', 'spy']:
        path = ROOT/f'{case}-terminal-fragments.json'
        if not path.exists():
            continue
        rows = decode_fragments(json.loads(path.read_text()), case)
        (ROOT/f'{case}-summary.json').write_text(json.dumps(rows,indent=2)+'\n')
        results[case] = rows
        if case != 'probe':
            try:
                audits.append(audit_metrics(rows))
            except ValueError as error:
                audits.append(dict(passed=False,case=case,error=str(error)))
    if set(results) != {'probe','capm','spy'}:
        raise ValueError('All three study cases required for comparison')
    prior = json.loads((ROOT/'superseded/attempt3/capm-summary.json').read_text())
    old_full = next(r for r in prior if r['kind']=='full')
    new_full = next(r for r in results['capm'] if r['kind']=='full')
    extension_path = ROOT/'accounting-retest-budget.json'
    extension = json.loads(extension_path.read_text()) if extension_path.exists() else {'attempts':[]}
    completed_retest = any(a['case']=='capm' and a['status']=='completed-aggregate-audit-passed' for a in extension['attempts'])
    repeated = completed_retest and len(prior)==len(results['capm']) and all(a['metrics']==b['metrics'] for a,b in zip(prior,results['capm'])) and old_full['audit']['calendar_hash']==new_full['audit']['calendar_hash']
    if not repeated:
        audits.append(dict(case='technical-retest',passed=False,error='No verified repaired CAPM run; final job executed stale SPY case'))
    calendars = [next(r for r in results[c] if r['kind']=='full')['audit']['calendar_hash'] for c in ['capm','spy']]
    parity = len(set(calendars)) == 1 and calendars[0] is not None
    valid = all(a['passed'] for a in audits) and parity
    report = dict(study='capm-spy-v1', generated_utc=datetime.now(timezone.utc).isoformat(), comparison_eligible=valid, calendar_parity=parity, accounting_only_retest_reproduced=repeated, outcome='completed' if valid else 'provisional-accounting-retest-blocked', source_identity={c:[a['source_sha256'] for a in json.loads((ROOT/'budget.json').read_text())['attempts']+extension['attempts'] if a['case']==c and a['status'] in ['completed-accounting-audit-failed','completed-aggregate-audit-passed']][-1] for c in ['capm','spy']}, audits=audits, results=results, plan=plan)
    (OUT/'review.json').write_text(json.dumps(report,indent=2)+'\n')
    data = json.dumps(report,separators=(',',':')).replace('<','\\u003c')
    page = PAGE.replace('__DATA__',data)
    (OUT/'index.html').write_text(page)
    files = [Path('research/plans/capm-spy-v1.json'),Path('research/quantconnect/capm_study.py'),Path('research/quantconnect/sector_metrics.py'),Path('research/capm_review.py'),Path('scripts/build_capm_review.py'),Path('scripts/capm_study.py'),Path('scripts/audit_capm_review.py'),Path('tests/test_capm_review.py'),Path('research/quantconnect/sources/capm_framework_original.py'),Path('research/quantconnect/sources/LICENSE-QuantConnect.txt'),ROOT/'budget.json']
    files += [ROOT/'probe-gate.json',ROOT/'editor-verification.json',ROOT/'server-reload-check.json',ROOT/'retest-reconciliation.json']
    if extension_path.exists():
        files += [extension_path,Path('research/plans/capm-spy-v1.accounting-retest.json'),ROOT/'prepared-build-status.txt']
    files += sorted((ROOT/'superseded/attempt1').glob('*'))+sorted((ROOT/'superseded/attempt3').glob('*'))+sorted((ROOT/'superseded/checkpoint5').glob('*'))
    files += sorted(ROOT.glob('*-visible-status.txt'))+sorted(ROOT.glob('attempt5-*.json'))
    files += sorted(ROOT.glob('*-source.py'))+sorted(ROOT.glob('*-terminal-fragments.json'))+sorted(ROOT.glob('*-summary.json'))
    files += [p for p in [OUT/'browser-audit.json',OUT/'review-preview.png',ROOT/'offline-check.log'] if p.exists()]
    files += [OUT/'review.json',OUT/'index.html']
    manifest = dict(study='capm-spy-v1',status='completed-aggregate-audit' if valid else 'completed-audit-failure', generated_utc=report['generated_utc'],files=[dict(path=str(p),bytes=p.stat().st_size,sha256=hashlib.sha256(p.read_bytes()).hexdigest()) for p in files])
    (OUT/'manifest.json').write_text(json.dumps(manifest,indent=2)+'\n')
    print(json.dumps(dict(output=str(OUT),eligible=valid,audits=audits),indent=2))


PAGE = '''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title>CAPM alternative vs SPY · bounded study</title><style>
:root{color-scheme:light;--ink:#1b282b;--muted:#59686a;--bg:#f3f0e9;--line:#d4d9d3;--capm:#186d68;--spy:#bd673b}*{box-sizing:border-box}body{margin:0;background:var(--bg);color:var(--ink);font:15px/1.5 system-ui,sans-serif}main{max-width:1250px;margin:36px auto;padding:0 26px}h1{font-size:38px;line-height:1.15;max-width:840px;margin:9px 0 18px;letter-spacing:-1px}h2{font-size:21px;margin-top:32px}.eyebrow{letter-spacing:2px;font-size:12px;text-transform:uppercase;color:var(--muted)}.note{max-width:930px;color:var(--muted)}.status{display:inline-block;padding:5px 12px;border:1px solid #a5b7a6;border-radius:20px;background:#e2eddf}.warn{background:#f7e2d3;border-color:#d7a47c}.grid{display:grid;grid-template-columns:1fr 1fr;gap:18px}.card{background:#fffdf8;border:1px solid var(--line);padding:22px;border-radius:12px}.card h3{margin:0 0 12px}.metrics{display:grid;grid-template-columns:repeat(3,1fr);gap:18px}.metric small{display:block;color:var(--muted)}.metric strong{font-size:25px;letter-spacing:-.5px}.capm{color:var(--capm)}.spy{color:var(--spy)}table{border-collapse:collapse;width:100%;background:#fffdf8;font-size:13px}th,td{padding:10px 8px;text-align:right;border-bottom:1px solid var(--line);white-space:nowrap}th:first-child,td:first-child{text-align:left}thead{background:#e3e8df}th{font-weight:600}.scroll{overflow:auto;border:1px solid var(--line);border-radius:10px}select{background:#fffdf8;border:1px solid var(--line);padding:9px 12px;font-size:14px;border-radius:7px}button{cursor:pointer}.legend{display:flex;gap:20px;color:var(--muted)}.legend span::before{content:'● ';color:inherit}.chart{background:#fffdf8;border:1px solid var(--line);padding:16px;border-radius:12px;margin:14px 0}.chart svg{width:100%;height:290px}details{border:1px solid var(--line);background:#fffdf8;padding:12px 18px;border-radius:9px;margin:12px 0}summary{cursor:pointer;font-weight:600}a{color:var(--capm)}.flow{padding:16px;border-left:3px solid var(--capm);background:#e5ece2;font-family:monospace}footer{margin:36px 0;color:var(--muted);font-size:12px}@media(max-width:800px){.grid{grid-template-columns:1fr}h1{font-size:31px}.metrics{gap:12px}.metric strong{font-size:21px}}
</style></head><body><main><div class="eyebrow">Quant Trading Lab · CAPM–SPY v1 · development evidence</div><h1>Does the CAPM framework alternative improve on simply holding SPY?</h1><span id="status" class="status"></span><p class="note">2016–2025 · $300,000 simulated capital · native IB fees · 25bp slippage per fill · 1% cash buffer · 6% debit financing. Two fixed cases; no search or optimization.</p><div id="cards" class="grid"></div><h2>Year by year</h2><p class="note">Annual drawdown starts from the preceding year-end NAV and resets the peak each year. Full-period underwater metrics carry the peak across years.</p><label for="metric">Compare metric </label><select id="metric"><option value="ret">Annual return</option><option value="dd">Annual maximum drawdown</option><option value="sharpe">Annual Sharpe</option><option value="annual_calmar">Annual Calmar</option><option value="uw_fraction">Time underwater, % sessions</option><option value="longest_uw">Longest underwater, sessions</option></select><div class="legend"><span class="capm">CAPM alternative</span><span class="spy">SPY buy and hold</span></div><div id="chart" class="chart"></div><div class="scroll"><table id="annual"></table></div><h2>What the comparison means</h2><div id="lesson" class="card"></div><h2>Dependencies, execution and evidence</h2><div class="flow">Licensed source → order-free access gate → two fixed simulations → aggregate integrity checks → comparison</div><details open><summary>Free-data and runtime probe</summary><div id="probe"></div></details><details><summary>Costs, accounting and audit limits</summary><div id="audit"></div></details><details><summary>Definitions and source differences</summary><p>Sharpe: sample daily return mean divided by sample standard deviation × √252; risk-free return zero. Full Calmar: calendar-day CAGR ÷ absolute full drawdown. Annual Calmar: annual total return ÷ absolute within-year drawdown. Drawdown uses closing portfolio marks, not intraday worst losses. Time underwater counts closes below the running peak; longest calendar duration ends at the last underwater mark, excluding recovery day. “Open at end” means the latest drawdown has not recovered.</p><p>The Apache-2.0 official LEAN example uses 29 fixed legacy tickers, reverse-regression intercept ranking of stock returns against SPY, two selected stock names plus an explicitly subscribed SPY benchmark eligible for constant insights, equal weighting, immediate execution and a 1% per-security drawdown stop. This is a framework alternative, not an exact hosted tutorial reproduction or conventional CAPM alpha. The common minute SPY clock can change benchmark insight timing relative to the original daily subscription. The fixed universe, sample exposure and mapping choices limit generalization. No raw prices or daily NAV paths were exported.</p><p><a href="https://github.com/QuantConnect/Lean/blob/22404ea28b8d3f3c9eb74d6ed9f0444426f8e417/Algorithm.Python/CapmAlphaRankingFrameworkAlgorithm.py">Pinned licensed source</a> · <a href="https://www.quantconnect.com/project/38510582">Hosted project</a> · <a href="review.json">Aggregate evidence</a> · <a href="manifest.json">Artifact manifest</a></p></details><footer>No independent alpha, untouched out-of-sample result, live broker validation or portfolio drawdown guarantee is established. Prior failed attempts remain in the private evidence folder.</footer></main><script>
const D=__DATA__;const cases=['capm','spy'];const name={capm:'CAPM framework alternative',spy:'SPY buy and hold'};const full=c=>D.results[c].find(r=>r.kind==='full');const annual=c=>D.results[c].filter(r=>r.kind==='annual').sort((a,b)=>a.year-b.year);const pct=v=>v==null?'—':(100*v).toFixed(2)+'%';const num=v=>v==null?'—':v.toFixed(2);const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
statusEl=document.getElementById('status');statusEl.textContent=D.comparison_eligible?'Completed · native-accounting checks passed':'Completed · comparison not eligible';if(!D.comparison_eligible)statusEl.classList.add('warn');
document.getElementById('cards').innerHTML=cases.map(c=>{let m=full(c).metrics;return `<article class="card"><h3 class="${c}">${name[c]}</h3><p class="${D.audits.find(a=>a.case===c)?.passed?'note':'warn'}">${D.audits.find(a=>a.case===c)?.passed?'Aggregate accounting checks passed':'Provisional: accounting check unresolved; no qualified ranking'}</p><div class="metrics">${[['CAGR',pct(m.cagr)],['Maximum drawdown',pct(m.dd)],['Sharpe',num(m.sharpe)],['Calmar',num(m.calmar)],['Time underwater',pct(m.uw_fraction)],['Longest underwater',m.longest_uw+' sessions']].map(([k,v])=>`<div class="metric"><small>${k}</small><strong>${v}</strong></div>`).join('')}</div><p class="note">Total return ${pct(m.ret)} · longest underwater ${m.longest_uw_days} calendar days · terminal drawdown: ${m.censored?'open':'recovered'}</p></article>`}).join('');
document.getElementById('annual').innerHTML='<thead><tr><th>Year · case</th><th>Return</th><th>Max DD</th><th>Sharpe</th><th>Calmar</th><th>Underwater</th><th>Longest sessions</th><th>Calendar days</th><th>Open at end</th></tr></thead><tbody>'+annual('capm').map((r,i)=>cases.map(c=>{let m=annual(c)[i].metrics;return `<tr><td><span class="${c}">${r.year} · ${c==='capm'?'CAPM':'SPY'}</span></td><td>${pct(m.ret)}</td><td>${pct(m.dd)}</td><td>${num(m.sharpe)}</td><td>${num(m.annual_calmar)}</td><td>${pct(m.uw_fraction)}</td><td>${m.longest_uw}</td><td>${m.longest_uw_days}</td><td>${m.censored?'Yes':'No'}</td></tr>`}).join('')).join('')+'</tbody>';
function chart(){let key=document.getElementById('metric').value;let rows=annual('capm');let vals=cases.flatMap(c=>annual(c).map(r=>r.metrics[key]??0));let lo=Math.min(0,...vals),hi=Math.max(0,...vals);let pad=Math.max((hi-lo)*.1,.01);lo-=pad;hi+=pad;let y=v=>245-(v-lo)/(hi-lo)*215;let zero=y(0);let body=`<line x1="45" y1="${zero}" x2="1135" y2="${zero}" stroke="#94a19b"/>`;for(let j=0;j<5;j++){let v=lo+(hi-lo)*j/4;body+=`<text x="38" y="${y(v)+4}" text-anchor="end" fill="#59686a" font-size="11">${['ret','dd','uw_fraction'].includes(key)?(100*v).toFixed(0)+'%':v.toFixed(1)}</text>`;}rows.forEach((r,i)=>{let x=62+i*106;cases.forEach((c,j)=>{let v=annual(c)[i].metrics[key];if(v==null)return;let yy=y(v);body+=`<rect x="${x+j*33}" y="${Math.min(yy,zero)}" width="28" height="${Math.max(Math.abs(yy-zero),1)}" fill="${c==='capm'?'#186d68':'#bd673b'}"><title>${r.year} ${name[c]}: ${v}</title></rect>`});body+=`<text x="${x+31}" y="274" text-anchor="middle" fill="#59686a" font-size="12">${r.year}</text>`});document.getElementById('chart').innerHTML=`<svg viewBox="0 0 1160 290" role="img" aria-label="Annual comparison of the selected metric">${body}</svg>`;}
document.getElementById('metric').addEventListener('change',chart);chart();let a=full('capm').metrics,b=full('spy').metrics;let wins=annual('capm').filter((r,i)=>r.metrics.ret>annual('spy')[i].metrics.ret).length;document.getElementById('lesson').innerHTML=`<p>CAPM’s CAGR differs from SPY by <strong>${((a.cagr-b.cagr)*100).toFixed(2)} percentage points</strong>; full Calmar differs by <strong>${num(a.calmar-b.calmar)}</strong>. CAPM has the higher annual return in <strong>${wins} of 10 years</strong>.</p><p>Compare the closing drawdown and time-underwater figures together. Smaller drawdown does not necessarily mean faster recovery. A per-stock 1% stop can still leave a much larger portfolio drawdown, including gaps and repeated losses.</p><p>CAPM produced ${full('capm').audit.fills.toLocaleString()} fills versus ${full('spy').audit.fills} for SPY, with $${full('capm').audit.fees.toLocaleString()} in fees. Its fixed 25bp slippage model applies to every fill. This fixed 25bp scenario supports investigating repeated exits/re-entry and turnover. Other costs and risk-rule ablations remain untested, so exact causal loss attribution and behavior at lower costs remain unproven.</p><p>${D.comparison_eligible?'The aggregate checks passed, subject to the limits below.':'Audit failures prevent treating these cases as an eligible financial comparison.'} This is descriptive development evidence, not a selection signal or a forecast.</p>`;
let p=D.results.probe[0];document.getElementById('probe').innerHTML=`<p>NumPy ${esc(p.numpy)} · pandas ${esc(p.pandas)} · ${p.universe_count} original fixed symbols · ${p.fills} fills · ${p.rejects} rejected/canceled orders. LEAN v18209.</p><div class="scroll"><table><thead><tr><th>Year checkpoint</th><th>Regression ready</th><th>Aligned calendars</th><th>Minute history</th><th>Issues</th></tr></thead><tbody>${p.years.map(r=>`<tr><td>${r.year}</td><td>${r.ready}</td><td>${r.aligned}</td><td>${r.minute}</td><td>${esc(JSON.stringify(r.issues))}</td></tr>`).join('')}</tbody></table></div><p>Annual checkpoints demonstrate the sampled histories, not every daily observation or vendor accuracy.</p>`;
document.getElementById('audit').innerHTML=`<p>Calendar parity: ${D.calendar_parity}. Accounting-only retest reproduced prior CAPM performance: ${D.accounting_only_retest_reproduced}. ${D.accounting_only_retest_reproduced?'The repaired run preserves the prior performance.':'The last reserved job executed stale SPY code, so no repaired CAPM result is available. A new run requires a separately authorized budget extension.'} Native-book identity is checked; there is no independent replay of every cash, dividend and fill event. Drawdown/time-underwater paths stayed hosted. Framework exits and native splits/dividends/mapping are part of the modeled result. Native normalization defaults were retained; corporate-action and adjusted-price/cash behavior were not independently replayed.</p><div class="scroll"><table><thead><tr><th>Case</th><th>Fills</th><th>Rejected/canceled</th><th>Fees USD</th><th>Financing USD</th><th>Max close gross</th><th>Book residual USD</th></tr></thead><tbody>${cases.map(c=>{let a=full(c).audit;return `<tr><td>${c}</td><td>${a.fills}</td><td>${a.rejects}</td><td>${num(a.fees)}</td><td>${num(a.interest)}</td><td>${num(a.max_gross)}x</td><td>${num(a.native_book_residual)}</td></tr>`}).join('')}</tbody></table></div><p>${D.audits.map(x=>esc(x.case+': '+(x.passed?'aggregate checks passed':x.error))).join('<br>')}</p>`;
</script></body></html>'''

if __name__ == '__main__':
    main()
